using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

public sealed class DbFixture : IDisposable
{
    public string Connection { get; } = "memory";
    public void Dispose() { }
}

/// <summary>
/// Shared lazy instance so both test classes use the same DbFixture
/// (mirrors the xUnit ICollectionFixture scope).
/// </summary>
internal static class SharedDbFixture
{
    private static readonly Lazy<DbFixture> s_instance = new(() => new DbFixture());
    public static DbFixture Instance => s_instance.Value;

    [AssemblyCleanup]
    public static void Cleanup() => s_instance.Value.Dispose();
}

// Assembly-level parallelization matches xUnit's default (parallel across classes).
// The two Db-collection classes opt out individually with [DoNotParallelize].
[assembly: Parallelize(Workers = 0, Scope = ExecutionScope.ClassLevel)]

